CREATE OR REPLACE FUNCTION public.default_expense_payment_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.account_id IS NULL THEN SELECT id INTO NEW.account_id FROM public.financial_accounts WHERE active AND ownership='empresa' AND test_reset_batch IS NULL ORDER BY created_at,id LIMIT 1; IF NEW.account_id IS NULL THEN RAISE EXCEPTION 'Não há uma conta interna ativa para preservar o registro do pagamento.'; END IF; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.default_expense_payment_account() FROM PUBLIC,anon,authenticated; CREATE TRIGGER a_default_expense_payment_account BEFORE INSERT ON public.expense_payments FOR EACH ROW EXECUTE FUNCTION public.default_expense_payment_account();